import{_ as a,a as t}from"./chunks/welcome.Czrg1zlC.js";import{_ as i}from"./chunks/schedule.ZDSBYxh8.js";import{_ as s,o as n,c as o,a3 as r}from"./chunks/framework.CchDE9cb.js";const l="/capacitylens/assets/first-run.On4-x7HQ.gif",_=JSON.parse('{"title":"First steps after installing","description":"What happens the first time you sign in, and how to find your way around the schedule.","frontmatter":{"title":"First steps after installing","description":"What happens the first time you sign in, and how to find your way around the schedule."},"headers":[],"relativePath":"getting-started/first-steps.md","filePath":"getting-started/first-steps.md","lastUpdated":null}'),h={name:"getting-started/first-steps.md"};function c(d,e,p,u,g,f){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="first-steps-after-installing" tabindex="-1">First steps after installing <a class="header-anchor" href="#first-steps-after-installing" aria-label="Permalink to &quot;First steps after installing&quot;">​</a></h1><p>Once you&#39;ve <a href="/capacitylens/getting-started/install">installed CapacityLens</a> and claimed the <a href="/capacitylens/reference/glossary">Owner</a> account, this page covers the first few minutes inside the app: signing in, the welcome message, and getting oriented on the schedule.</p><p><img src="'+l+'" alt="Animated recording of the full first-run flow: sign in, choose a company, read the welcome, land on the schedule"></p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><p>Every visit after you&#39;ve created the Owner account shows the plain sign-in screen: email and password.</p><p><img src="'+a+'" alt="CapacityLens sign-in screen with email and password fields"></p><h2 id="the-welcome-message" tabindex="-1">The welcome message <a class="header-anchor" href="#the-welcome-message" aria-label="Permalink to &quot;The welcome message&quot;">​</a></h2><p>Once per device, CapacityLens shows a short orientation explaining what it is — and what it isn&#39;t. It&#39;s worth reading once: it sets expectations that CapacityLens plans people, not paperwork, and it won&#39;t show again on that device.</p><p><img src="'+t+'" alt="Welcome to CapacityLens dialog explaining it is a resourcing tool, not a project management tool"></p><h2 id="finding-your-way-around-the-schedule" tabindex="-1">Finding your way around the schedule <a class="header-anchor" href="#finding-your-way-around-the-schedule" aria-label="Permalink to &quot;Finding your way around the schedule&quot;">​</a></h2><p>After the welcome message, you land on <a href="/capacitylens/guide/the-schedule">the schedule</a> — the one screen the whole product is built around. On a fresh install it&#39;s empty, with a Getting Started panel prompting you to add clients, projects and people before you drag out any allocations.</p><p><img src="'+i+'" alt="The Schedule view with people grouped by discipline, allocation bars, utilisation and a holiday block"></p><p>A few things worth knowing before you start adding data:</p><ul><li>People are grouped by <a href="/capacitylens/reference/glossary">discipline</a> down the left.</li><li>Allocation bars span the weeks a <a href="/capacitylens/reference/glossary">person</a> is booked, and can be tentative, confirmed or completed.</li><li><a href="/capacitylens/reference/glossary">Utilisation</a> percentages update live as you drag allocations around.</li><li>Time off — holiday, sick, unpaid — sits on the same canvas as work, so capacity is always honest.</li></ul><p>See <a href="/capacitylens/guide/the-schedule">The schedule</a> for the full walkthrough of the view, and <a href="/capacitylens/guide/people-and-placeholders">People and placeholders</a> for adding your team.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p><a href="/capacitylens/getting-started/invite-your-team">Invite your team</a> so the rest of your studio can sign in too — or go straight to <a href="/capacitylens/guide/the-schedule">The schedule</a> if you&#39;re setting things up solo first.</p>',17)])])}const b=s(h,[["render",c]]);export{_ as __pageData,b as default};
